UPDATE agent_invocation
   SET fencing_token = #{newFencingToken}
 WHERE tenant_id = #{tenantId}::uuid AND run_id = #{runId}::uuid
   AND fencing_token < #{newFencingToken}
   AND status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELLED', 'TIMED_OUT', 'UNKNOWN')

UPDATE agent_invocation
   SET status = #{status}, reason_code = #{reasonCode},
       output_digest = #{outputDigest}, finished_at = #{finishedAt}
 WHERE tenant_id = #{tenantId}::uuid AND invocation_id = #{invocationId}::uuid
   AND fencing_token = #{fencingToken}
   AND status NOT IN ('SUCCEEDED', 'FAILED', 'CANCELLED', 'TIMED_OUT', 'UNKNOWN')
